            IOUtils.copy(input, output);
            input.close();
            output.close();
        } catch (IOException exception) {
            monitor.setCanceled(true);
            throw new InvocationTargetException(exception, "Can't unzip ffmpeg.exe");
        }
        monitor.worked(1);
        monitor.done();
    }

