            for (int i = 0; i < zipFiles.length; i++) {
                if (zipFiles[i] != null) {
                    bufferedZipStreams[i].close();
                    emailSender.send(emails[i], zipFiles[i]);
                    zipFiles[i].delete();
                }
            }
