        } catch (IOException iox) {
            LOG.log(Level.WARNING, "Could not load services descriptor: " + url.toString(), iox);
        } finally {
            finalClose(bReader);
            finalClose(reader);
            finalClose(inStream);
        }
        return result;
    }

